// Package wgdata serves the vanilla 26.3 data needed by world generation,
// structures and mob spawning: data-pack JSON (worldgen registries, loot
// tables, tags, dimension types, mob variants, ...), structure template NBT
// and selected data generator reports. The data is generated by
// tools/worldgendata and embedded from internal/data/gen/worldgen.
//
// Returned byte slices are shared with the cache and must not be modified.
package wgdata

import (
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"sort"
	"strings"
	"sync"

	blob "github.com/levitskyyy/KremenMC/internal/data/gen/worldgen"
)

// Registry directory aliases for names that changed between versions.
var aliases = map[string]string{
	"worldgen/configured_feature": "worldgen/feature",
	"worldgen/configured_carver":  "worldgen/carver",
	"structure_template":          "structure",
}

type segCache struct {
	once sync.Once
	b    []byte
	err  error
}

// Pack is a read-only view of an encoded container. It is safe for
// concurrent use.
type Pack struct {
	blob  []byte
	paths []string
	ents  []entry
	segs  []segment
	cache []segCache
	index map[string]int

	keys    map[string][]string
	tagKeys map[string][]string

	builtinOnce sync.Once
	builtin     map[string][]string
	builtinSet  map[string]map[string]bool

	tagMu    sync.Mutex
	tagCache map[string][]string
}

var (
	loadOnce sync.Once
	loaded   *Pack
	loadErr  error
)

// Load returns the embedded pack, decoding its index on first use.
func Load() (*Pack, error) {
	loadOnce.Do(func() { loaded, loadErr = Open(blob.Data) })
	return loaded, loadErr
}

// Open decodes a container produced by Encode. b must stay unmodified.
func Open(b []byte) (*Pack, error) {
	paths, ents, segs, err := decodeIndex(b)
	if err != nil {
		return nil, err
	}
	p := &Pack{
		blob:     b,
		paths:    paths,
		ents:     ents,
		segs:     segs,
		cache:    make([]segCache, len(segs)),
		index:    make(map[string]int, len(paths)),
		keys:     map[string][]string{},
		tagKeys:  map[string][]string{},
		tagCache: map[string][]string{},
	}
	for i, path := range paths {
		p.index[path] = i
		reg, key, tag, ok := classify(path)
		if !ok {
			continue
		}
		if tag {
			p.tagKeys[reg] = append(p.tagKeys[reg], key)
		} else {
			p.keys[reg] = append(p.keys[reg], key)
		}
	}
	for _, m := range []map[string][]string{p.keys, p.tagKeys} {
		for _, ks := range m {
			sort.Strings(ks)
		}
	}
	return p, nil
}

// classify maps "data/<ns>/<registry>/<path>.<ext>" to its registry and
// "<ns>:<path>" key. Registries are one directory deep, except worldgen/*.
func classify(path string) (reg, key string, tag, ok bool) {
	rest, ok := strings.CutPrefix(path, "data/")
	if !ok {
		return "", "", false, false
	}
	ns, rest, ok := strings.Cut(rest, "/")
	if !ok {
		return "", "", false, false
	}
	if r, ok := strings.CutPrefix(rest, "tags/"); ok {
		rest, tag = r, true
	}
	if strings.HasPrefix(rest, "datapacks/") {
		return "", "", false, false
	}
	n := 1
	if strings.HasPrefix(rest, "worldgen/") {
		n = 2
	}
	i := -1
	for range n {
		j := strings.IndexByte(rest[i+1:], '/')
		if j < 0 {
			return "", "", false, false
		}
		i += j + 1
	}
	reg, file := rest[:i], rest[i+1:]
	dot := strings.LastIndexByte(file, '.')
	if dot <= 0 {
		return "", "", false, false
	}
	return reg, ns + ":" + file[:dot], tag, true
}

func normRegistry(r string) string {
	r = strings.TrimPrefix(r, "minecraft:")
	if a, ok := aliases[r]; ok {
		return a
	}
	return r
}

func splitKey(key string) (ns, path string) {
	if ns, path, ok := strings.Cut(key, ":"); ok {
		return ns, path
	}
	return "minecraft", key
}

func qualify(key string) string {
	ns, path := splitKey(key)
	return ns + ":" + path
}

// File returns the raw contents stored at a container path, such as
// "data/minecraft/worldgen/biome/plains.json" or "reports/registries.json".
func (p *Pack) File(path string) ([]byte, bool) {
	i, ok := p.index[path]
	if !ok {
		return nil, false
	}
	e := p.ents[i]
	seg, err := p.segment(e.seg)
	if err != nil {
		return nil, false
	}
	return seg[e.off : e.off+e.n : e.off+e.n], true
}

func (p *Pack) segment(i int) ([]byte, error) {
	c := &p.cache[i]
	c.once.Do(func() {
		s := p.segs[i]
		c.b, c.err = inflate(p.blob[s.off:s.off+s.clen], s.rlen)
		if c.err != nil {
			c.err = fmt.Errorf("wgdata: segment %d: %w", i, c.err)
		}
	})
	return c.b, c.err
}

// Paths returns every container path in sorted order. The result is shared.
func (p *Pack) Paths() []string { return p.paths }

// JSON returns the minified data-pack JSON of a registry entry, e.g.
// JSON("worldgen/noise_settings", "overworld").
func (p *Pack) JSON(registry, key string) ([]byte, bool) {
	ns, path := splitKey(key)
	return p.File("data/" + ns + "/" + normRegistry(registry) + "/" + path + ".json")
}

// Keys returns the sorted, namespaced keys of a data-driven registry.
// Keys("structure") lists structure templates. The result is shared.
func (p *Pack) Keys(registry string) []string { return p.keys[normRegistry(registry)] }

// Registries returns the sorted names of all registries that have entries.
func (p *Pack) Registries() []string {
	rs := make([]string, 0, len(p.keys))
	for r := range p.keys {
		rs = append(rs, r)
	}
	sort.Strings(rs)
	return rs
}

// TagKeys returns the sorted, namespaced tag names (without '#') of a
// registry. The result is shared.
func (p *Pack) TagKeys(registry string) []string { return p.tagKeys[normRegistry(registry)] }

// TagJSON returns the unresolved tag file.
func (p *Pack) TagJSON(registry, key string) ([]byte, bool) {
	ns, path := splitKey(strings.TrimPrefix(key, "#"))
	return p.File("data/" + ns + "/tags/" + normRegistry(registry) + "/" + path + ".json")
}

// Template returns the uncompressed NBT of a structure template.
func (p *Pack) Template(key string) ([]byte, bool) {
	ns, path := splitKey(key)
	return p.File("data/" + ns + "/structure/" + path + ".nbt")
}

// Report returns a data generator report by its path under the reports
// directory, e.g. "registries.json" or "biome_parameters/minecraft/overworld.json".
func (p *Pack) Report(path string) ([]byte, bool) {
	return p.File("reports/" + strings.TrimPrefix(path, "/"))
}

// Builtin returns the entries of a code-defined registry from the
// registries.json report, ordered by protocol ID, e.g.
// Builtin("worldgen/feature_type"). The result is shared.
func (p *Pack) Builtin(registry string) ([]string, bool) {
	p.loadBuiltin()
	es, ok := p.builtin[qualify(registry)]
	return es, ok
}

// BuiltinRegistries returns the sorted names of the registries in
// registries.json.
func (p *Pack) BuiltinRegistries() []string {
	p.loadBuiltin()
	rs := make([]string, 0, len(p.builtin))
	for r := range p.builtin {
		rs = append(rs, r)
	}
	sort.Strings(rs)
	return rs
}

func (p *Pack) loadBuiltin() {
	p.builtinOnce.Do(func() {
		p.builtin = map[string][]string{}
		p.builtinSet = map[string]map[string]bool{}
		raw, ok := p.Report("registries.json")
		if !ok {
			return
		}
		var rep map[string]struct {
			Entries map[string]struct {
				ProtocolID int `json:"protocol_id"`
			} `json:"entries"`
		}
		if json.Unmarshal(raw, &rep) != nil {
			return
		}
		for name, r := range rep {
			es := make([]string, len(r.Entries))
			set := make(map[string]bool, len(r.Entries))
			for e, v := range r.Entries {
				if v.ProtocolID >= 0 && v.ProtocolID < len(es) {
					es[v.ProtocolID] = e
				}
				set[e] = true
			}
			p.builtin[name] = es
			p.builtinSet[name] = set
		}
	})
}

// exists reports whether id is a known element of registry. Registries the
// pack knows nothing about accept everything.
func (p *Pack) exists(reg, id string) bool {
	if _, ok := p.keys[reg]; ok {
		ns, path := splitKey(id)
		_, ok := p.index["data/"+ns+"/"+reg+"/"+path+".json"]
		return ok
	}
	p.loadBuiltin()
	if set, ok := p.builtinSet["minecraft:"+reg]; ok {
		return set[id]
	}
	return true
}

// Tag returns the members of a tag with nested tags expanded in declaration
// order, duplicates removed and missing optional entries dropped, e.g.
// Tag("worldgen/biome", "#is_overworld"). It reports false if the tag or a
// required entry does not exist.
func (p *Pack) Tag(registry, key string) ([]string, bool) {
	reg := normRegistry(registry)
	id := qualify(strings.TrimPrefix(key, "#"))
	p.tagMu.Lock()
	defer p.tagMu.Unlock()
	out, err := p.resolveTag(reg, id, map[string]bool{})
	if err != nil {
		return nil, false
	}
	return slices.Clone(out), true
}

var errMissing = errors.New("missing tag")

type tagValue struct {
	ID       string
	Required bool
}

func (v *tagValue) UnmarshalJSON(b []byte) error {
	if len(b) > 0 && b[0] == '"' {
		v.Required = true
		return json.Unmarshal(b, &v.ID)
	}
	var o struct {
		ID       string `json:"id"`
		Required *bool  `json:"required"`
	}
	if err := json.Unmarshal(b, &o); err != nil {
		return err
	}
	v.ID, v.Required = o.ID, o.Required == nil || *o.Required
	return nil
}

// resolveTag must be called with tagMu held.
func (p *Pack) resolveTag(reg, id string, stack map[string]bool) ([]string, error) {
	ck := reg + "\x00" + id
	if out, ok := p.tagCache[ck]; ok {
		return out, nil
	}
	if stack[ck] {
		return nil, fmt.Errorf("tag cycle at %s #%s", reg, id)
	}
	raw, ok := p.TagJSON(reg, id)
	if !ok {
		return nil, errMissing
	}
	var t struct {
		Values []tagValue `json:"values"`
	}
	if err := json.Unmarshal(raw, &t); err != nil {
		return nil, fmt.Errorf("tag %s #%s: %w", reg, id, err)
	}
	stack[ck] = true
	defer delete(stack, ck)

	out := []string{}
	seen := map[string]bool{}
	add := func(e string) {
		if !seen[e] {
			seen[e] = true
			out = append(out, e)
		}
	}
	for _, v := range t.Values {
		if ref, ok := strings.CutPrefix(v.ID, "#"); ok {
			sub, err := p.resolveTag(reg, qualify(ref), stack)
			if errors.Is(err, errMissing) && !v.Required {
				continue
			}
			if err != nil {
				return nil, err
			}
			for _, e := range sub {
				add(e)
			}
			continue
		}
		e := qualify(v.ID)
		if !v.Required && !p.exists(reg, e) {
			continue
		}
		add(e)
	}
	p.tagCache[ck] = out
	return out, nil
}
